SELECT MONTH(opened_date) AS opened_month, AVG(sqft) AS avg_sqft, ROUND((100 * SUM(CASE WHEN region = 'West' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_west, SUM(CASE WHEN city = 'New York' THEN sqft ELSE 0 END) AS new_york_sqft FROM stores WHERE store_name IS NOT NULL AND opened_date <= '2025-03-01' AND city IN ('Singapore', 'New York', 'Bangkok') GROUP BY 1 HAVING SUM(CASE WHEN city = 'New York' THEN sqft ELSE 0 END) > 45 ORDER BY avg_sqft, opened_month LIMIT 20;
